package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.widget.*;import org.json.*;import java.util.concurrent.*;
public final class MotionEditor {
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Animation").setMessage(String.valueOf(e.getCause()==null?e:e.getCause())).setPositiveButton("Close",null).show();}
 public static void attach(Activity a,LinearLayout col,JSONObject player){Button b=new Button(a);b.setText("Animation · Copy native motion");b.setAllCaps(false);col.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{b.setEnabled(false);new Thread(()->{try{JSONObject data=new JSONObject(manage(a,"ui712_motion_get",player));a.runOnUiThread(()->{b.setEnabled(true);if(!a.isFinishing())form(a,player,data);});}catch(Exception e){a.runOnUiThread(()->{b.setEnabled(true);error(a,e);});}},"MotionLoad").start();});}
 private static void form(Activity a,JSONObject player,JSONObject data){LinearLayout col=new LinearLayout(a);col.setOrientation(1);int pad=Math.round(14*a.getResources().getDisplayMetrics().density);col.setPadding(pad,pad,pad,pad);TextView note=new TextView(a);note.setText("Current donor: "+data.optString("name")+"\nCopies run/dribble/posture/arm and free-kick/penalty/corner motion fields only. Keeps body, face, stats and celebrations. Unique passing/shooting linked to player identity is not proven transferable.");col.addView(note);EditText search=new EditText(a);search.setSingleLine(true);search.setHint("Search a native donor · e.g. David Beckham");col.addView(search);TextView count=new TextView(a);col.addView(count);ListView list=new ListView(a);col.addView(list,new LinearLayout.LayoutParams(-1,Math.round(300*a.getResources().getDisplayMetrics().density)));LinearLayout nav=new LinearLayout(a);Button back=new Button(a),next=new Button(a);back.setText("Previous");next.setText("Next");nav.addView(back);nav.addView(next);col.addView(nav);AlertDialog d=new AlertDialog.Builder(a).setTitle("Animation donor").setView(col).setNegativeButton("Close",null).create();Handler timer=new Handler(Looper.getMainLooper());ExecutorService worker=Executors.newSingleThreadExecutor();int[] epoch={0},page={0};JSONArray[] rows={new JSONArray()};boolean[] alive={true};
 Runnable refresh=()->{int request=++epoch[0],pg=page[0];String q=search.getText().toString();count.setText("Searching…");worker.execute(()->{try{JSONObject r=new JSONObject(manage(a,"ui712_motion_search",new JSONObject().put("query",q).put("page",pg)));a.runOnUiThread(()->{if(!alive[0]||request!=epoch[0]||a.isFinishing())return;rows[0]=r.optJSONArray("items");String[] labels=new String[rows[0].length()];for(int i=0;i<labels.length;i++){JSONObject item=rows[0].optJSONObject(i);labels[i]=item.optString("name")+"\n"+item.optString("id");}list.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_list_item_1,labels));count.setText(r.optInt("total")+" native cards · Page"+(pg+1));back.setEnabled(pg>0);next.setEnabled((pg+1)*40<r.optInt("total"));});}catch(Exception e){a.runOnUiThread(()->{if(alive[0]&&request==epoch[0])count.setText(String.valueOf(e.getCause()==null?e:e.getCause()));});}});};
 search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int n,int after){}public void onTextChanged(CharSequence s,int start,int before,int n){page[0]=0;++epoch[0];timer.removeCallbacksAndMessages(null);timer.postDelayed(refresh,180);}public void afterTextChanged(Editable e){}});back.setOnClickListener(v->{if(page[0]>0){page[0]--;refresh.run();}});next.setOnClickListener(v->{page[0]++;refresh.run();});list.setOnItemClickListener((parent,view,pos,id)->{JSONObject source=rows[0].optJSONObject(pos);new AlertDialog.Builder(a).setTitle("Copy motion from "+source.optString("name")+"?").setMessage("Eight verified native motion fields will be resolved from the actual donor record. Save before Enter Game, then close and reopen the app.").setNegativeButton("Cancel",null).setPositiveButton("Copy",(dlg,which)->{list.setEnabled(false);worker.execute(()->{try{JSONObject req=new JSONObject(player.toString()).put("source",source.optString("id"));JSONObject out=new JSONObject(manage(a,"ui712_motion_apply",req));if(!out.optBoolean("saved"))throw new Exception("Save not confirmed");a.runOnUiThread(()->{if(alive[0])d.dismiss();Toast.makeText(a,"Saved. Reopen the app.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{list.setEnabled(true);error(a,e);});}});}).show();});d.setOnDismissListener(x->{alive[0]=false;timer.removeCallbacksAndMessages(null);worker.shutdownNow();});d.show();ResponsiveUi.fit(a,d);refresh.run();}
}
